from pathlib import Path
import json
w=Path('/tmp/claim-audit-9bdqk6ur');r=json.loads((w/'input/report-ledger.json').read_text());s=json.loads((w/'input/source-ledger.json').read_text())
def ev(a):
 for p,d in s.items():
  if a in d:return {'path':p,'anchor':a,'quote':d[a]}
 raise ValueError(a)
def pr(t,target,relation='auxiliary'):return {'module':'Audit','theorem':'Audit.'+t,'relation':relation,'target':target}
f=[]
def add(n,q,anchors,rules,assumptions,reason,state,arg,formal,proofs,limits,reco):
 k=f'CE-{n:02d}';a=f'report-ce{n:02d}'
 f.append({'claim_id':k,'report_anchor':a,'report_quote':r[a],'question':q,'evidence':[ev(a) for a in anchors],'rules':rules,'assumptions':assumptions,'reasoning':[str(i+1)+'. '+t for i,t in enumerate(reason)],'semantic_state':state,'argument_status':arg,'formal_status':formal,'proofs':proofs,'limits':limits,'recommendation':reco})
add(1,'Does the complete finite supplied manifest for R17 on EU-A contain exactly three distinct entry IDs, without extending that statement to all dependencies or deployed instances?', ['inventory-p1','inventory-p2'],['The brief expressly limits the universe to the three inventory-p2 rows. Exactly three distinct IDs requires both a three-element list and no duplicate IDs.'],['The anchored table is faithfully transcribed and accepted as complete for this exported manifest only.'],['inventory-p1 identifies the export as the R17 EU-A manifest and explicitly separates manifest entries from runtime measurements.','inventory-p2 gives A-01, A-02 and A-03. The row count is three and every ID differs from the other two.','The checked finite theorem establishes both length three and no duplicates. This directly supports the literal report claim within its stated universe.'],'supported','sufficient','proved',[pr('claim01','Audit.manifestIds.length = 3 ∧ Audit.manifestIds.Nodup','supports')],['The proof establishes a finite supplied-inventory fact only. It does not prove completeness of deployment dependencies, runtime instances, build authenticity or source provenance.'],'Retain the claim with its exact manifest-only scope and table citation.')
add(2,'What do the supplied sources establish about enabled TLS on the same inbound API listener for R17, EU-A, at 2030-03-14T11:45:00Z?', ['qa-p1','qa-p2','ops-p1','ops-p2','ops-p3','policy-p3'],['Retain separate testimony provenance. Neither the brief nor policy-p3 gives priority to QA, Operations, later timestamps, or signature markers. ops-p2 expressly uses disabled as negation of the identical enabled-state proposition.'],['Both transcriptions are evidence that their attributed authors made the stated assertions; neither is treated as an independently measured deployment fact or authenticated signature.'],['Supporting evidence: qa-p2 affirms enabled TLS for the exact listener, release, target and instant.','Counterevidence: ops-p2 explicitly denies that same proposition and confirms identical scope. This is direct contradictory testimony, not a difference between library presence and listener state.','ops-p3 says the later Operations document does not revoke QA. No reconciliation or precedence rule is supplied. Both raw probe/configuration records are absent.','The result is conflicting evidence for the exact claim. The auxiliary theorem records matching scopes, distinct provenance and opposing assertion polarities; it does not prove both world states.'],'both','disputed','auxiliary',[pr('claim02Conflict','Audit.qa.scope = Audit.ops.scope ∧ Audit.qa.issuer ≠ Audit.ops.issuer ∧ Audit.qa.assertsEnabled = true ∧ Audit.ops.assertsEnabled = false')],['Actual TLS enabled state remains unresolved. A signed-looking marker is not authenticated cryptographic evidence. No real deployment was inspected.'],'Report both attributed assertions and seek the raw probe/configuration output or an independently grounded reconciliation before asserting a settled TLS state.')
add(3,'Does absence of a penetration-test certificate in the supplied package establish that no R17 EU-A penetration test occurred at any time before 2030-03-14T12:00:00Z?', ['inventory-p1','inventory-p3'],['Attachment inventory completeness is not event-history completeness. inventory-p3 explicitly says attachment absence is not a statement about whether a test happened elsewhere.'],['The supplied attachment list accurately records no included penetration-test certificate; no closed-world assumption is made about historical tests.'],['The cited inventory supports a narrower statement: no penetration-test certificate is attached.','The independent full-corpus review found no supplied test event record and no exhaustive test-history assertion. inventory-p3 expressly prevents extending attachment absence to test nonoccurrence.','The proposed inference loses the distinction between a document being absent here and an event never occurring before cutoff. A test without a transferred certificate is a permissible possibility.','Two hypothetical histories share the observed certificate absence but disagree on test occurrence. The auxiliary theorem demonstrates this failure of entailment. Neither supplies actual counterevidence proving a test happened.'],'undetermined','insufficient_support','auxiliary',[pr('claim03Alternatives','Audit.possibleTest.certificateAttached = false ∧ Audit.possibleNoTest.certificateAttached = false ∧ Audit.possibleTest.testOccurredBeforeCutoff = true ∧ Audit.possibleNoTest.testOccurredBeforeCutoff = false')],['The support gap and invalid absence-based step do not refute the underlying no-test claim. The actual test history is unknown, and the corpus is not an exhaustive event log.'],'Replace the event-level conclusion with the supported attachment absence, or obtain an exhaustive scoped test-history record or explicit reliable event-level evidence.')
add(4,'Do the supplied POL-4 implication and QA smoke-check success establish that R17 on EU-A was Ready at cutoff, preserving both required antecedents and the one-way rule?', ['policy-p1','policy-p2','policy-p3','qa-p3','inventory-p2'],['policy-p2 states only (SmokePassed AND SecurityApproved) implies Ready. It neither asserts approval nor provides a converse or a necessary-and-sufficient definition.','An implication can establish its consequent only when its full antecedent is available. policy-p3 supplies no approval-from-silence or priority rule.'],['For evaluating the proposed argument, grant the attributed QA smoke-check assertion for all three manifest entries as its SmokePassed premise. This does not authenticate QA or invent security approval.'],['The inventory gives the same three entries referenced in qa-p3, so the smoke-success premise has documentary support for the finite population.','policy-p1 defines SecurityApproved as an authorized reviewer approving this release and target. policy-p2 expressly does not grant or assert it; qa-p3 does not assert all security requirements passed. The corpus supplies no established approval premise.','The report incorrectly treats a two-premise conditional plus one premise as enough to infer Ready. The conditional theorem shows what would follow if both premises were independently available.','A model with SmokePassed=true, SecurityApproved=false and Ready=false satisfies the policy and the supplied smoke premise, so these premises do not entail readiness.','A second model with SmokePassed=true, SecurityApproved=false and Ready=true also satisfies this sufficient-only policy. Hence neither missing approval evidence nor this rule proves actual non-readiness.'],'undetermined','invalid_inference','auxiliary',[pr('conditionalReadiness','∀ (Smoke Security Ready : Prop), ((Smoke ∧ Security) → Ready) → Smoke → Security → Ready'),pr('claim04MissingPremise','Audit.policy true false false ∧ Audit.policy true false true ∧ ¬ ((Audit.policy true false false ∧ true = true) → false = true)')],['The countermodel refutes the report\'s entailment claim, not the actual Ready proposition. SecurityApproved=false is hypothetical rather than inferred from missing records. The conditional theorem is not an executed certification of this release.'],'State the missing authorized-security-approval premise and obtain source-linked evidence for it before applying this rule; leave actual readiness undetermined on the supplied argument.')
add(5,'Does CE-05 appendix citation establish that an independent reviewer verified the CE-04 readiness conclusion for R17 EU-A before cutoff, or does the proposed support merely repeat the claim?', ['excerpt-p1','excerpt-ce05','excerpt-appendix','inventory-p3'],['A report assertion cannot independently support itself. The brief and excerpt-p1 restrict archive transcription to wording and citation structure, not factual review confirmation. Absence of a supplied artifact does not prove absence of a historical review.'],['The archive accurately preserves the selected report\'s two cited passages and their links; this assumption concerns wording only, not the truth of a verification assertion.'],['The selected CE-05 cites report-appendix-p1 for independent verification. That appendix says verified but cites back to CE-05 and attaches no separate review artifact.','excerpt-ce05 and excerpt-appendix preserve these same two edges, while excerpt-p1 expressly disclaims independent confirmation. The archive therefore documents the circular citation; it is not an independent reviewer.','inventory-p3 confirms that no independent readiness review is attached and explicitly separates attachment absence from whether a review occurred elsewhere.','The two-edge graph provides no independent evidentiary grounding for the existence, independence, scope or timing of a reviewer. The auxiliary theorem records the cycle and no supplied independent artifact.','The proposed justification is circular and invalid. Whether an independent review actually happened before cutoff remains undetermined rather than refuted.'],'undetermined','invalid_inference','auxiliary',[pr('claim05Cycle','(Audit.CitationNode.reportClaim, Audit.CitationNode.appendix) ∈ Audit.citationEdges ∧ (Audit.CitationNode.appendix, Audit.CitationNode.reportClaim) ∈ Audit.citationEdges ∧ Audit.CitationNode.independentReview ∉ Audit.suppliedReviewArtifacts')],['The cycle proves a defect in justification, not that independent review never occurred. The source transcript is not an independent readiness assessment. No actual reviewer was contacted.'],'Obtain a separate review artifact identifying the reviewer, independence, reviewed release/target, readiness conclusion, basis and pre-cutoff timestamp; remove circular verification language until supported.')
add(6,'Does a QA signature marker establish cryptographic verification of QA authenticity before cutoff, distinguishing marker presence, actual signature validity and execution of a verification procedure?', ['qa-p1','inventory-p3'],['Literal signature-marker text is not a signing key, cryptographic signature, certificate chain or verification result. The mandate distinguishes a marker from verified authenticity, and the package is not an exhaustive event history.'],['The qa-p1 transcription faithfully contains the displayed marker. No assumption is made about its cryptographic validity, identity binding or whether a verification process ran elsewhere.'],['qa-p1 supplies a scenario signature marker and issuer/author metadata. It explicitly supplies no key, signature bytes, chain or authenticity verification result.','Independent search of the supplied package found no verification artifact establishing the claimed cryptographic procedure or its pre-cutoff timing. The marker alone is not that missing premise.','Two hypothetical histories can contain the identical marker and absent supplied verification result while disagreeing on whether verification happened before cutoff. The auxiliary theorem records that non-entailment.','The authenticity-verification assertion lacks sufficient support. This does not prove a forged signature, invalid signature, or absence of any historical verification.'],'undetermined','insufficient_support','auxiliary',[pr('claim06Alternatives','Audit.possibleVerified.markerPresent = true ∧ Audit.possibleUnverified.markerPresent = true ∧ Audit.possibleVerified.verificationArtifactSupplied = false ∧ Audit.possibleUnverified.verificationArtifactSupplied = false ∧ Audit.possibleVerified.verifiedBeforeCutoff = true ∧ Audit.possibleUnverified.verifiedBeforeCutoff = false')],['No cryptographic authentication was executed. Actual signature validity and whether verification occurred before cutoff both remain unknown. The model does not simulate cryptography.'],'Describe the marker as unverified metadata unless supplied with signature material, trusted identity/key binding, and a documented verification result timestamped before cutoff.')
(w/'findings.json').write_text(json.dumps(f,indent=2,ensure_ascii=False)+'\n')
